SELECT *, ROW_NUMBER() OVER (ORDER BY status_bits, id) AS event_seq, ROUND(pressure / SUM(pressure) OVER (PARTITION BY device_code), 4) AS pressure_share, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_temp_c, MIN(temp_c) OVER (PARTITION BY device_code) AS device_code_min_temp_c, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_bits FROM device_readings;
